import{_ as d,C as n,o as s,c as t,j as a,a as r,E as c,a3 as i}from"./chunks/framework.DEy3KOfk.js";const v=JSON.parse('{"title":"BedrockAddonManager","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/bedrock-addon-manager/docs/index.md"},"headers":[],"relativePath":"packages/bedrock-addon-manager/docs/index.md","filePath":"packages/bedrock-addon-manager/docs/index.md","lastUpdated":1791428389000}'),p={name:"packages/bedrock-addon-manager/docs/index.md"},l={id:"bedrockaddonmanager",tabindex:"-1",class:"component-page-title"},k={class:"component-page-title__version"};function h(u,e,m,f,g,b){const o=n("Badge");return s(),t("div",null,[a("h1",l,[e[0]||(e[0]=a("span",{class:"component-page-title__text"},[r("BedrockAddonManager "),a("a",{class:"header-anchor",href:"#bedrockaddonmanager","aria-label":'Permalink to "BedrockAddonManager"'},"​")],-1)),a("span",k,[c(o,{type:"info",text:"v0.0.0"})])]),e[1]||(e[1]=i('<p>BedrockAddonManager scans Bedrock <code>.mcpack</code> and <code>.mcaddon</code> files, reads pack manifests, and serves the selected resource packs over HTTP. Use it to prepare pack downloads for Bedrock players.</p><p>Pumpkin does not currently expose an API for sending resource-pack offers to players. The plugin can host and describe packs, but it cannot make clients download or require them; the <code>packs.force</code> setting has no effect until Pumpkin supports delivery.</p><h2 id="typical-setup" tabindex="-1">Typical setup <a class="header-anchor" href="#typical-setup" aria-label="Permalink to &quot;Typical setup&quot;">​</a></h2><p>Install <code>bedrock-addon-manager.wasm</code> in the server&#39;s <code>plugins/</code> directory and restart. Put pack files in <code>plugins/data/BedrockAddonManager/packs/</code>, then run <code>/baddon reload</code> or restart again. <code>/baddon list</code> shows each discovered pack and its effective settings. The plugin does not modify <code>pumpkin.toml</code>.</p><p>Choose a URL Bedrock clients can reach. Set <code>web.public_url</code> when serving packs through a known address or reverse proxy. If it is empty and the server binds to <code>0.0.0.0</code>, the plugin can ask UPnPumpkin to forward <code>web.port</code>; without a successful mapping it falls back to a loopback address, which only works on the server machine. See the setup and troubleshooting pages in this section for network and pack-format details.</p><h2 id="pack-selection" tabindex="-1">Pack selection <a class="header-anchor" href="#pack-selection" aria-label="Permalink to &quot;Pack selection&quot;">​</a></h2><p>The plugin reads each pack&#39;s <code>manifest.json</code> for its UUID, version, and flags. An <code>.mcaddon</code> may contain both behavior and resource packs; only its resource packs are extracted and served because Pumpkin cannot use behavior packs. Per-file overrides can disable a pack, set its order, or provide an external <code>download_url</code>. Overrides for extracted packs use the name shown by <code>/baddon list</code>.</p><p>The built-in server uses plain HTTP. Put a TLS reverse proxy in front of it when clients need an HTTPS URL, or host the files elsewhere and configure download URLs.</p>',8))])}const P=d(p,[["render",h]]);export{v as __pageData,P as default};
